package com.snakeskinbandanafilter;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("bandanafilter")
public interface BandanaFilterConfig extends Config
{
	@ConfigItem(
			keyName = "enabled",
			name = "Enabled",
			description = "Hide other players unless they are wearing a snakeskin bandana."
	)
	default boolean enabled()
	{
		return true;
	}

	@ConfigItem(
			keyName = "hideSelfIfNotWearing",
			name = "Hide me if not wearing bandana",
			description = "If enabled, your own player will be hidden when you are not wearing a snakeskin bandana."
	)
	default boolean hideSelfIfNotWearing()
	{
		return false;
	}

	@ConfigItem(
			keyName = "neverHideFriends",
			name = "Never hide friends",
			description = "If enabled, friends are never hidden even if they do not wear the bandana."
	)
	default boolean neverHideFriends()
	{
		return true;
	}

	@ConfigItem(
			keyName = "neverHideClanMembers",
			name = "Never hide clan members",
			description = "If enabled, clan members are never hidden even if they do not wear the bandana."
	)
	default boolean neverHideClanMembers()
	{
		return true;
	}

	@ConfigItem(
			keyName = "neverHideFriendsChat",
			name = "Never hide friends chat members",
			description = "If enabled, members of your current friends chat are never hidden even if they do not wear the bandana."
	)
	default boolean neverHideFriendsChat()
	{
		return true;
	}
}

package com.snakeskinbandanafilter;

import com.google.inject.Provides;
import javax.inject.Inject;

import net.runelite.api.Client;
import net.runelite.api.ItemID;
import net.runelite.api.Player;
import net.runelite.api.PlayerComposition;
import net.runelite.api.Renderable;
import net.runelite.api.kit.KitType;

import net.runelite.client.callback.RenderCallback;
import net.runelite.client.callback.RenderCallbackManager;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;

@PluginDescriptor(
		name = "Snakeskin Bandana Filter",
		description = "Hides players unless they are wearing a snakeskin bandana.",
		tags = {"hide", "players", "bandana", "snakeskin"}
)
public class BandanaFilterPlugin extends Plugin
{
	private static final int BANDANA_ITEM_ID = ItemID.SNAKESKIN_BANDANA;

	@Inject
	private Client client;

	@Inject
	private BandanaFilterConfig config;

	@Inject
	private RenderCallbackManager renderCallbackManager;

	private final RenderCallback renderCallback = new RenderCallback()
	{
		@Override
		public boolean addEntity(final Renderable renderable, final boolean ui)
		{
			if (ui)
			{
				return true;
			}

			if (!config.enabled())
			{
				return true;
			}

			if (!(renderable instanceof Player))
			{
				return true;
			}

			final Player player = (Player) renderable;
			final Player local = client.getLocalPlayer();

			if (local == null)
			{
				return true;
			}

			final boolean isLocal = player == local;

			// Exemptions for other players
			if (!isLocal)
			{
				if (config.neverHideFriends() && player.isFriend())
				{
					return true;
				}

				if (config.neverHideClanMembers() && player.isClanMember())
				{
					return true;
				}

				if (config.neverHideFriendsChat() && player.isFriendsChatMember())
				{
					return true;
				}
			}

			final PlayerComposition composition = player.getPlayerComposition();
			if (composition == null)
			{
				// If we cannot read their equipment yet, do not hide them
				return true;
			}

			final boolean wearingBandana = isWearingBandana(composition);

			// Local player logic
			if (isLocal)
			{
				if (!config.hideSelfIfNotWearing())
				{
					return true;
				}

				return wearingBandana;
			}

			// Other players logic
			return wearingBandana;
		}
	};

	@Provides
	BandanaFilterConfig provideConfig(final ConfigManager configManager)
	{
		return configManager.getConfig(BandanaFilterConfig.class);
	}

	@Override
	protected void startUp()
	{
		renderCallbackManager.register(renderCallback);
	}

	@Override
	protected void shutDown()
	{
		renderCallbackManager.unregister(renderCallback);
	}

	private static boolean isWearingBandana(final PlayerComposition composition)
	{
		final int headValue = getHeadEquipmentValue(composition);
		if (headValue < 0)
		{
			return false;
		}

		// Accept raw item ID or ITEM_OFFSET plus item ID
		if (headValue == BANDANA_ITEM_ID)
		{
			return true;
		}

		if (headValue >= PlayerComposition.ITEM_OFFSET
				&& (headValue - PlayerComposition.ITEM_OFFSET) == BANDANA_ITEM_ID)
		{
			return true;
		}

		return false;
	}

	private static int getHeadEquipmentValue(final PlayerComposition composition)
	{
		final int[] equipmentIds = composition.getEquipmentIds();
		if (equipmentIds != null)
		{
			final int idx = KitType.HEAD.getIndex();
			if (idx >= 0 && idx < equipmentIds.length)
			{
				return equipmentIds[idx];
			}
		}

		return composition.getEquipmentId(KitType.HEAD);
	}
}

package com.snakeskinbandanafilter;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class BandanaFilterPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(BandanaFilterPlugin.class);
		RuneLite.main(args);
	}
}
